// PROTOTYPE A — Phase rail + scene hub (V1-descended). Persistent horizontal phase rail; Production opens a scene hub; scene work uses stage lenses.
function railChip(p){const st=phSt(p.id),active=(U.view===p.id)||(p.grp==='prod'&&U.view.match(/^(hub|scene)$/));
 const icon={done:'●',prog:'◐',todo:'○',skipped:'↷',bypassed:'⤼',optional:'◌',defer:'◌'}[st];
 const col={done:'var(--ok)',prog:'var(--warn)',todo:'#aaa',skipped:'#888',bypassed:'#888',optional:'#aaa'}[st];
 return `<div onclick="go({view:'${p.id}',scene:null,shot:null})" title="${p.n} — ${PH_NOTE[p.id]||p.d}" style="cursor:pointer;padding:6px 10px;border-radius:8px;border:1px solid ${active?'var(--acc)':'var(--line)'};background:${active?'#eef1fd':'#fff'};${['skipped','bypassed'].includes(st)?'border-style:dashed;':''}min-width:0"><div class="row" style="gap:5px"><span style="color:${col}">${icon}</span><b>${p.n}</b></div><div class="sm mut" style="white-space:nowrap">${st==='bypassed'?'bypassed':st==='skipped'?'skipped by you':st==='done'?'done':st==='prog'?'in progress':st==='optional'?'optional':'—'}</div></div>`}
function viewA(){
 const story=PHASES.filter(p=>p.grp==='story'),rest=[phase('world')];
 const rail=`<div class="row" style="padding:8px 14px;background:#fff;border-bottom:1px solid var(--line);gap:6px;flex-wrap:nowrap;overflow:auto">
  <span class="sm mut">PROJECT</span>${story.map(railChip).join('<span class="mut">›</span>')}<span class="mut">›</span>${railChip(phase('world'))}<span style="width:10px"></span><span class="sm mut">PRODUCTION</span>
  <div onclick="go({view:'hub',scene:null,shot:null})" style="cursor:pointer;padding:6px 10px;border-radius:8px;border:1px solid ${U.view.match(/^(hub|scene)$/)?'var(--acc)':'var(--line)'};background:${U.view.match(/^(hub|scene)$/)?'#eef1fd':'#fff'}"><b>Scene Hub</b><div class="sm mut">${SHOTS.length?SCENES.filter(s=>s.shots.length).length+' scenes planned':'—'}</div></div><span class="mut">›</span>${railChip(phase('review'))}</div>`;
 const top=`<div class="row" style="padding:8px 14px;background:#fff;border-bottom:1px solid var(--line)"><button class="ghost">← Projects</button><b style="font-size:15px">${STATE==='new'?'Untitled project':'The Landlord Sketch'}</b>${STATE==='new'?'':chip('prog','6:30 · 16:9')}<span class="sp"></span>${STATE==='new'?'':runtimeMeter()+filmProgress()+staleNote()+'<span class="chip">Spend $41.20</span>'}</div>`;
 let body='';
 if(STATE==='new'&&U.view==='home'){U.view='input'}
 if(U.view==='home')U.view='hub';
 if(U.view==='hub')body=hubA(); else if(U.view==='scene')body=sceneA(); else body=`<div class="scroll" style="flex:1">${phasePage(U.view)}</div>`;
 const onboard=STATE==='new'?`<div class="row" style="padding:8px 14px;background:#eef1fd;border-bottom:1px solid #d5dcf6"><b>First time here?</b><span>The rail above is the whole journey. Only <b>Input</b> is needed to begin — everything else is open and any phase can be skipped. Recommended path is dotted; you can click anywhere.</span><span class="sp"></span><button>Dismiss</button></div>`:'';
 return top+rail+onboard+`<div style="flex:1;min-height:0;display:flex;flex-direction:column">${body}</div>`}
function hubA(){
 if(!SHOTS.length)return `<div class="pad mut">Scenes appear here after the Master Narrative is accepted.</div>`;
 const f=U.filter;const sc=SCENES.filter(s=>f==='all'||(f==='attn'&&s.shots.some(x=>['failed','review'].includes(x.st)||x.stale)));
 return `<div class="row" style="padding:10px 14px;gap:8px;border-bottom:1px solid var(--line);background:#fff"><h3 style="margin:0">Scene Hub</h3><span class="sp"></span>
  <button class="${f==='all'?'pri':''}" onclick="go({filter:'all'},1)">All ${SCENES.length}</button><button class="${f==='attn'?'pri':''}" onclick="go({filter:'attn'},1)">Needs attention</button>
  <span style="width:12px"></span><button>Draft shot plans for 2 scenes</button><button>Generate all approved shots…</button><button>Select scenes ▾</button></div>
 <div class="scroll" style="flex:1;background:#fff"><table style="width:100%;border-collapse:collapse">${sc.map(s=>{const t=scProg(s);return `<tr style="cursor:pointer;border-bottom:1px solid var(--line)" onclick="go({view:'scene',scene:${s.i},shot:null,lens:'shots'})"><td style="padding:8px 14px;width:36px" class="mut">${s.n}</td><td style="width:230px"><b>${s.title}</b><div class="sm mut">${s.slug}</div></td><td style="width:60px" class="mut">${s.shots.length?s.shots.length+' shots':'no plan'}</td><td style="width:320px">${s.shots.length?stackBar(t,s.shots.length,10):'<span class="mut sm">Not planned yet · <u>Draft plan</u></span>'}</td><td class="sm mut">${s.shots.length?`${t.selected||0}/${s.shots.length} selected`+(t.failed?` · <span style="color:var(--fail)">${t.failed} failed</span>`:'')+(t.review?` · ${t.review} need a pick`:''):''} ${s.shots.some(x=>x.stale)?'<span class="stale">possibly out of date</span>':''}</td><td>›</td></tr>`}).join('')}</table></div>`}
function sceneA(){
 const s=SCENES[U.scene],lenses=[['shots','Shot list'],['previs','Direction'],['frames','Frames'],['takes','Takes'],['audio','Audio']];
 const list=`<div class="scroll" style="width:210px;border-right:1px solid var(--line);background:#fff"><div class="pad sm mut" style="padding-bottom:4px"><a onclick="go({view:'hub',scene:null,shot:null})" style="cursor:pointer;color:var(--acc)">← Scene Hub</a></div>${SCENES.map(x=>`<div onclick="go({scene:${x.i},shot:null})" style="padding:5px 12px;cursor:pointer;${x.i===s.i?'background:#eef1fd;':''}"><div class="sm"><b>${x.n}.</b> ${x.title}</div>${x.shots.length?stackBar(scProg(x),x.shots.length,4):''}</div>`).join('')}</div>`;
 const lens=U.lens;
 const cell=sh=>lens==='frames'?`<div style="width:130px;cursor:pointer" onclick="go({shot:'${sh.id}'},1)">${thumb(sh,130,73)}<div class="sm">${sh.id} ${sh.st==='planned'?'<span class="mut">no frame</span>':'frame ✓'}</div></div>`
  :lens==='takes'?`<div style="width:150px;cursor:pointer" onclick="go({shot:'${sh.id}'},1)">${thumb(sh,150,84)}<div class="sm">${sh.id} · ${sh.takes} take${sh.takes==1?'':'s'}</div><div class="sm" style="color:${SHOT_STATES[sh.st][1]}">${SHOT_STATES[sh.st][0]}</div></div>`:'';
 const main=lens==='shots'?`<table style="width:100%;border-collapse:collapse">${s.shots.map(sh=>`<tr onclick="go({shot:'${sh.id}'},1)" style="cursor:pointer;border-bottom:1px solid var(--line);${U.shot===sh.id?'background:#eef1fd':''}"><td style="padding:6px 10px"><b>${sh.id}</b></td><td>${sh.title}</td><td class="mut">${sh.dur}s</td><td><span class="chip" style="border-color:${SHOT_STATES[sh.st][1]}"><i class="dot ${sh.st==='generating'?'gen':''}" style="background:${SHOT_STATES[sh.st][1]}"></i>${SHOT_STATES[sh.st][0]}</span> ${sh.stale?'<span class="stale">out of date?</span>':''}</td></tr>`).join('')||'<tr><td class="pad mut">No shot plan yet. <button>Draft shot plan</button></td></tr>'}</table>`
  :(lens==='frames'||lens==='takes')?`<div class="pad row" style="flex-wrap:wrap;align-items:flex-start;gap:12px">${s.shots.map(cell).join('')}</div>`:`<div class="pad mut">(${lens} lens: optional step for this scene — no shots use it yet. Clicking is never required.)</div>`;
 const detail=`<div class="scroll" style="width:380px;border-left:1px solid var(--line);background:#fff">${U.shot&&shotById(U.shot)&&shotById(U.shot).sc===s.i?shotDetail(shotById(U.shot)):'<div class="pad mut">Select a shot for detail.</div>'}</div>`;
 return `<div style="display:flex;flex:1;min-height:0">${list}<div style="flex:1;display:flex;flex-direction:column;min-width:0"><div class="row" style="padding:8px 14px;background:#fff;border-bottom:1px solid var(--line)"><b style="font-size:14px">Scene ${s.n}: ${s.title}</b><span class="mut sm">${s.slug} · ${s.shots.length} shots · ${fmt(s.dur)}</span><span class="sp"></span>${lenses.map(l=>`<button class="${U.lens===l[0]?'pri':''}" onclick="go({lens:'${l[0]}'},1)">${l[1]}</button>`).join('')}</div>
  <div class="banner quiet sm" style="margin:8px 14px 0;${s.shots.some(x=>x.stale)?'':'display:none'}">Maren’s look changed after these shots were made. They are marked quietly; nothing is blocked.</div><div class="scroll" style="flex:1">${main}</div></div>${detail}</div>`}
